### 3. Production Service Implementation Skeleton

```cpp
#include "proto/user_service.grpc.pb.h"
#include <grpcpp/grpcpp.h>

namespace user_service {

class UserServiceImpl final : public UserService::Service {
 public:
  explicit UserServiceImpl(UserRepositoryInterface& repository)
      : repository_(repository) {}

  grpc::Status GetUser(grpc::ServerContext* context,
                       const GetUserRequest* request,
                       User* response) override {
    if (request->user_id().empty()) {
      return grpc::Status(grpc::StatusCode::INVALID_ARGUMENT, "user_id cannot be empty");
    }

    auto user_result = repository_.FindById(request->user_id());
    if (!user_result.has_value()) {
      return grpc::Status(grpc::StatusCode::NOT_FOUND, 
                          "User not found for ID: " + request->user_id());
    }

    *response = std::move(*user_result);
    return grpc::Status::OK;
  }

  grpc::Status CreateUser(grpc::ServerContext* context,
                          const CreateUserRequest* request,
                          User* response) override {
    const std::string& user_id = request->user().user_id();
    if (user_id.empty()) {
      return grpc::Status(grpc::StatusCode::INVALID_ARGUMENT, "user_id is required");
    }

    if (repository_.Exists(user_id)) {
      return grpc::Status(grpc::StatusCode::ALREADY_EXISTS, 
                          "User ID already exists: " + user_id);
    }

    auto saved_user = repository_.Save(request->user());
    *response = std::move(saved_user);
    return grpc::Status::OK;
  }

  grpc::Status UpdateUser(grpc::ServerContext* context,
                          const UpdateUserRequest* request,
                          User* response) override {
    const std::string& user_id = request->user().user_id();
    if (!repository_.Exists(user_id)) {
      return grpc::Status(grpc::StatusCode::NOT_FOUND, "User does not exist");
    }

    auto updated_user = repository_.Update(request->user(), request->update_mask());
    *response = std::move(updated_user);
    return grpc::Status::OK;
  }

  grpc::Status DeleteUser(grpc::ServerContext* context,
                          const DeleteUserRequest* request,
                          google::protobuf::Empty* response) override {
    if (!repository_.Exists(request->user_id())) {
      return grpc::Status(grpc::StatusCode::NOT_FOUND, "User does not exist");
    }

    repository_.Delete(request->user_id());
    return grpc::Status::OK;
  }

 private:
  UserRepositoryInterface& repository_;
};

}  // namespace user_service
```

