### 4. Legacy REST Adapter / Shim Implementation

```cpp
// Legacy adapter ensuring backward compatibility during phased cutover
class LegacyUserControllerAdapter {
 public:
  explicit LegacyUserControllerAdapter(std::unique_ptr<UserService::StubInterface> grpc_stub)
      : stub_(std::move(grpc_stub)) {}

  HttpResponse HandleGetLegacyUser(const HttpRequest& http_request) {
    grpc::ClientContext context;
    context.set_deadline(std::chrono::system_clock::now() + std::chrono::milliseconds(500));

    GetUserRequest rpc_request;
    rpc_request.set_user_id(http_request.GetPathParameter("id"));

    User rpc_response;
    grpc::Status status = stub_->GetUser(&context, rpc_request, &rpc_response);

    if (!status.ok()) {
      return MapGrpcStatusToHttpResponse(status);
    }

    std::string json_body;
    google::protobuf::util::MessageToJsonString(rpc_response, &json_body);
    return HttpResponse::Ok(json_body);
  }

 private:
  HttpResponse MapGrpcStatusToHttpResponse(const grpc::Status& status) {
    switch (status.error_code()) {
      case grpc::StatusCode::NOT_FOUND:
        return HttpResponse::NotFound(status.error_message());
      case grpc::StatusCode::INVALID_ARGUMENT:
        return HttpResponse::BadRequest(status.error_message());
      case grpc::StatusCode::ALREADY_EXISTS:
        return HttpResponse::Conflict(status.error_message());
      default:
        return HttpResponse::InternalServerError("RPC execution failed");
    }
  }

  std::unique_ptr<UserService::StubInterface> stub_;
};
```

