We enforce this programmatically using standard relative luminance formula ($L = 0.2126R + 0.7152G + 0.0722B$):

#### `tests/tokens/contrast.test.ts`
```typescript
import { describe, it, expect } from 'vitest';
import { colord, extend } from 'colord';
import a11yPlugin from 'colord/plugins/a11y';

extend([a11yPlugin]);

describe('Material 3 Contrast Ratio Compliance (WCAG AA)', () => {
  const darkTheme = {
    background: '#141218',
    surface: '#1D1B20',
    primary: '#D0BCFF',
    onPrimary: '#381E72',
    onSurface: '#E6E1E5',
    outline: '#938F99',
  };

  it('verifies Dark Mode primary text on dark surface meets AA standard (>= 4.5:1)', () => {
    const contrast = colord(darkTheme.primary).contrast(darkTheme.background);
    expect(contrast).toBeGreaterThanOrEqual(4.5); // Evaluates to ~9.6:1
  });

  it('verifies Dark Mode button text (on-primary) on primary fill meets AA standard', () => {
    const contrast = colord(darkTheme.onPrimary).contrast(darkTheme.primary);
    expect(contrast).toBeGreaterThanOrEqual(4.5); // Evaluates to ~7.8:1
  });

  it('verifies Dark Mode body text on surface meets AAA standard (>= 7.0:1)', () => {
    const contrast = colord(darkTheme.onSurface).contrast(darkTheme.surface);
    expect(contrast).toBeGreaterThanOrEqual(7.0); // Evaluates to ~12.5:1
  });
});
