import React, { useEffect, useState } from 'react';
import './UserSettingsView.scss';

export type ThemeMode = 'light' | 'dark' | 'system';

export interface UserSettingsProps {
  initialUsername?: string;
  initialEmail?: string;
}

export const UserSettingsView: React.FC<UserSettingsProps> = ({
  initialUsername = 'Alex Doe',
  initialEmail = 'alex.doe@example.com',
}) => {
  const [theme, setTheme] = useState<ThemeMode>(() => {
    return (localStorage.getItem('user-theme') as ThemeMode) || 'system';
  });
  const [username, setUsername] = useState(initialUsername);
  const [email, setEmail] = useState(initialEmail);

  useEffect(() => {
    const applyTheme = (mode: ThemeMode) => {
      const root = document.documentElement;
      if (mode === 'system') {
        const systemPrefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
        root.setAttribute('data-theme', systemPrefersDark ? 'dark' : 'light');
      } else {
        root.setAttribute('data-theme', mode);
      }
      localStorage.setItem('user-theme', mode);
    };

    applyTheme(theme);

    if (theme === 'system') {
      const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
      const handleChange = (e: MediaQueryListEvent) => {
        document.documentElement.setAttribute('data-theme', e.matches ? 'dark' : 'light');
      };
      mediaQuery.addEventListener('change', handleChange);
      return () => mediaQuery.removeEventListener('change', handleChange);
    }
  }, [theme]);

  return (
    <div className="user-settings-layout" data-testid="user-settings-view">
      <nav className="user-settings-layout__nav" aria-label="Settings Navigation">
        <button className="nav-item nav-item--active">General Preferences</button>
        <button className="nav-item">Account Security</button>
        <button className="nav-item">Notifications</button>
      </nav>

      <main className="user-settings-layout__content">
        <section className="settings-card">
          <h1 className="settings-card__title">User Settings</h1>
          <p className="settings-card__subtitle">
            Manage your interface appearance and personal information.
          </p>

          <div className="settings-card__section">
            <h2 className="settings-card__title" style={{ fontSize: '1.25rem' }}>Appearance</h2>
            <div className="theme-switcher-group" role="group" aria-label="Select theme mode">
              {(['light', 'dark', 'system'] as ThemeMode[]).map((mode) => (
                <button
                  key={mode}
                  type="button"
                  className="theme-btn"
                  aria-pressed={theme === mode}
                  onClick={() => setTheme(mode)}
                  data-testid={`theme-btn-${mode}`}
                >
                  {mode.charAt(0).toUpperCase() + mode.slice(1)}
                </button>
              ))}
            </div>
          </div>

          <div className="settings-card__section">
            <h2 className="settings-card__title" style={{ fontSize: '1.25rem' }}>Profile Information</h2>
            <div className="settings-field">
              <label htmlFor="username-input">Display Name</label>
              <input
                id="username-input"
                type="text"
                value={username}
                onChange={(e) => setUsername(e.target.value)}
              />
            </div>
            <div className="settings-field">
              <label htmlFor="email-input">Email Address</label>
              <input
                id="email-input"
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
              />
            </div>
            <button type="submit" className="btn-primary">Save Changes</button>
          </div>
        </section>
      </main>
    </div>
  );
};
