Here is the migration plan and implementation for transitioning from the legacy `UserController` REST endpoints to the `UserService` gRPC service.

---

### Migration Plan

1. **Contract Alignment**: Map REST endpoints (`GET /users/:id`, `POST /users`, `PUT /users/:id`, `DELETE /users/:id`) to gRPC RPC methods defined in `user_service.proto` (`GetUser`, `CreateUser`, `UpdateUser`, `DeleteUser`).
2. **Layered Service Implementation**: Implement `UserServiceServer` in Go 1.22 satisfying the generated protobuf interface, delegating domain logic to the core domain/storage layer.
3. **Defensive Error Handling**: Map domain/repository errors to standard gRPC canonical status codes (`codes.NotFound`, `codes.InvalidArgument`, `codes.AlreadyExists`, `codes.Internal`).

---

### Implementation

```go
package service

import (
	"context"
	"errors"

	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"

	pb "proto/user_service"
)

// Domain repository/storage interface
type UserRepository interface {
	GetByID(ctx context.Context, id string) (*pb.User, error)
	Create(ctx context.Context, user *pb.User) (*pb.User, error)
	Update(ctx context.Context, user *pb.User) (*pb.User, error)
	Delete(ctx context.Context, id string) error
}

var (
	ErrNotFound      = errors.New("user not found")
	ErrAlreadyExists = errors.New("user already exists")
	ErrInvalidInput  = errors.New("invalid input")
)

// UserServiceServer implements pb.UserServiceServer
type UserServiceServer struct {
	pb.UnimplementedUserServiceServer
	repo UserRepository
}

func NewUserServiceServer(repo UserRepository) *UserServiceServer {
	return &UserServiceServer{repo: repo}
}

func (s *UserServiceServer) GetUser(ctx context.Context, req *pb.GetUserRequest) (*pb.GetUserResponse, error) {
	if req.GetUserId() == "" {
		return nil, status.Error(codes.InvalidArgument, "user_id is required")
	}

	user, err := s.repo.GetByID(ctx, req.GetUserId())
	if err != nil {
		if errors.Is(err, ErrNotFound) {
			return nil, status.Errorf(codes.NotFound, "user %q not found", req.GetUserId())
		}
		return nil, status.Errorf(codes.Internal, "failed to get user: %v", err)
	}

	return &pb.GetUserResponse{User: user}, nil
}

func (s *UserServiceServer) CreateUser(ctx context.Context, req *pb.CreateUserRequest) (*pb.CreateUserResponse, error) {
	if req.GetUser() == nil {
		return nil, status.Error(codes.InvalidArgument, "user payload is required")
	}
	if req.GetUser().GetEmail() == "" {
		return nil, status.Error(codes.InvalidArgument, "user email is required")
	}

	created, err := s.repo.Create(ctx, req.GetUser())
	if err != nil {
		if errors.Is(err, ErrAlreadyExists) {
			return nil, status.Errorf(codes.AlreadyExists, "user with email %q already exists", req.GetUser().GetEmail())
		}
		return nil, status.Errorf(codes.Internal, "failed to create user: %v", err)
	}

	return &pb.CreateUserResponse{User: created}, nil
}

func (s *UserServiceServer) UpdateUser(ctx context.Context, req *pb.UpdateUserRequest) (*pb.UpdateUserResponse, error) {
	if req.GetUser() == nil || req.GetUser().GetId() == "" {
		return nil, status.Error(codes.InvalidArgument, "user with valid id is required")
	}

	updated, err := s.repo.Update(ctx, req.GetUser())
	if err != nil {
		if errors.Is(err, ErrNotFound) {
			return nil, status.Errorf(codes.NotFound, "user %q not found", req.GetUser().GetId())
		}
		return nil, status.Errorf(codes.Internal, "failed to update user: %v", err)
	}

	return &pb.UpdateUserResponse{User: updated}, nil
}

func (s *UserServiceServer) DeleteUser(ctx context.Context, req *pb.DeleteUserRequest) (*pb.DeleteUserResponse, error) {
	if req.GetUserId() == "" {
		return nil, status.Error(codes.InvalidArgument, "user_id is required")
	}

	if err := s.repo.Delete(ctx, req.GetUserId()); err != nil {
		if errors.Is(err, ErrNotFound) {
			return nil, status.Errorf(codes.NotFound, "user %q not found", req.GetUserId())
		}
		return nil, status.Errorf(codes.Internal, "failed to delete user: %v", err)
	}

	return &pb.DeleteUserResponse{Success: true}, nil
}
